#include <iostream>
#include <vector>

int main() {
    // C99/C++ loop-scoped variable demonstration
    int sum = 0;
    const int limit = 5;
    for (int i = 1; i <= limit; ++i) {
        sum += i;
    }
    // 'i' is out of scope here; sum is valid
    std::cout << "Loop sum: " << sum << "\n";

    // C++17 if-init statement localizing transient variables
    if (const std::vector<int> numbers = {10, 20, 30}; !numbers.empty()) {
        int runningTotal = 0;
        for (std::size_t idx = 0; idx < numbers.size(); ++idx) {
            runningTotal += numbers[idx];
            std::cout << "Element " << idx << ": " << numbers[idx] 
                      << ", Acc: " << runningTotal << "\n";
        }
    }
    std::cout << "Scope test passed.\n";
    return 0;
}

#include <iostream>
#include <limits>
#include <vector>
#include <optional>

// CERT compliant safe signed addition with precondition check
std::optional<int> safeAdd(int a, int b) {
    if (b > 0 && a > std::numeric_limits<int>::max() - b) {
        return std::nullopt; // Overflow prevented before execution
    }
    if (b < 0 && a < std::numeric_limits<int>::min() - b) {
        return std::nullopt; // Underflow prevented before execution
    }
    return a + b;
}

int main() {
    const int maxInt = std::numeric_limits<int>::max();

    // Test 1: Signed arithmetic overflow prevention
    const auto overflowResult = safeAdd(maxInt, 1);
    if (!overflowResult.has_value()) {
        std::cout << "Overflow prevented successfully.\n";
    }

    // Test 2: Valid arithmetic with return check
    const auto validResult = safeAdd(500, 250);
    if (validResult.has_value()) {
        std::cout << "Valid sum: " << *validResult << "\n";
    }

    // Test 3: Array bounds checking
    const std::vector<int> safeBuffer = {10, 20, 30};
    const std::size_t targetIndex = 2;
    if (targetIndex < safeBuffer.size()) {
        std::cout << "Element at index " << targetIndex << ": " 
                  << safeBuffer[targetIndex] << "\n";
    }

    return 0;
}
